say() { printf '%s\n' "$*"; }
die() { printf 'ERROR: %s\n' "$*" >&2; return 2; }
sha256_file() { sha256sum "$1" | awk '{print $1}'; }

safe_remove_tree() {
    local target="$1"
    case "$target" in
        "$WORK_PARENT"/work.*|"$META_INSTALL"|"$UPDATE_QC_INSTALL")
            [[ -n "$target" && "$target" != "/" ]] || return 2
            rm -rf -- "$target"
            ;;
        *)
            printf 'REFUSING_UNSAFE_REMOVE\t%s\n' "$target" >&2
            return 2
            ;;
    esac
}

restore_path_or_absence() {
    local target="$1"
    local backup="$2"
    local existed="$3"
    if [[ "$existed" == "true" ]]; then
        [[ -e "$backup" ]] || return 0
        mkdir -p "$(dirname "$target")"
        if [[ -d "$backup" ]]; then
            safe_remove_tree "$target" || true
            cp -a "$backup" "$target"
        else
            cp -a "$backup" "$target"
        fi
    else
        if [[ -d "$target" ]]; then
            safe_remove_tree "$target" || true
        elif [[ -e "$target" ]]; then
            rm -f -- "$target"
        fi
    fi
}

restore_ssot() {
    [[ -n "$BACKUP_DIR" && -d "$BACKUP_DIR" ]] || return 0
    say "Restoring pre-update SSOT state..."
    cp -a "$BACKUP_DIR/rnatr_ssot.py" "$SSOT_CLI" 2>/dev/null || true
    cp -a "$BACKUP_DIR/rnatr_ssot.sqlite" "$SSOT_DB" 2>/dev/null || true
    if [[ -f "$BACKUP_DIR/CURRENT_STATE.md" ]]; then
        cp -a "$BACKUP_DIR/CURRENT_STATE.md" "$SSOT_SUMMARY" 2>/dev/null || true
    elif [[ -e "$SSOT_SUMMARY" ]]; then
        rm -f -- "$SSOT_SUMMARY" 2>/dev/null || true
    fi
    if [[ -d "$BACKUP_DIR/exports" ]]; then
        if [[ -d "$SSOT_EXPORTS" ]]; then rm -rf -- "$SSOT_EXPORTS"; fi
        cp -a "$BACKUP_DIR/exports" "$SSOT_EXPORTS" 2>/dev/null || true
    elif [[ "$PREEXISTING_EXPORTS" == "false" && -d "$SSOT_EXPORTS" ]]; then
        rm -rf -- "$SSOT_EXPORTS" 2>/dev/null || true
    fi

    restore_path_or_absence "$SCRIPT_INSTALL" "$BACKUP_DIR/published/script" "$PREEXISTING_SCRIPT" || true
    restore_path_or_absence "$DESIGN_INSTALL" "$BACKUP_DIR/published/design" "$PREEXISTING_DESIGN" || true
    restore_path_or_absence "$META_INSTALL" "$BACKUP_DIR/published/meta" "$PREEXISTING_META" || true
    restore_path_or_absence "$UPDATE_QC_INSTALL" "$BACKUP_DIR/published/qc" "$PREEXISTING_QC" || true
}

create_failure_bundle() {
    local rc="$1"
    local line="$2"
    local command_text="$3"
    set +e
    mkdir -p "$WORK_ROOT/failure" "$DOWNLOADS"
    {
        printf 'metric\tvalue\n'
        printf 'update_version\t%s\n' "$UPDATE_VERSION"
        printf 'run_id\t%s\n' "$RUN_ID"
        printf 'exit_code\t%s\n' "$rc"
        printf 'line\t%s\n' "$line"
        printf 'command\t%s\n' "$command_text"
        printf 'mutation_started\t%s\n' "$MUTATION_STARTED"
        printf 'restoration_attempted\t%s\n' "$MUTATION_STARTED"
        printf 'timestamp_utc\t%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
    } > "$WORK_ROOT/failure/failure.tsv"
    local part="$FAILURE_BUNDLE.part.$$"
    rm -f -- "$part"
    tar -C "$WORK_PARENT" -czf "$part" "$(basename "$WORK_ROOT")" 2>/dev/null
    if [[ -s "$part" ]]; then
        mv -f "$part" "$FAILURE_BUNDLE"
        printf '%s  %s\n' "$(sha256_file "$FAILURE_BUNDLE")" "$(basename "$FAILURE_BUNDLE")" > "$FAILURE_BUNDLE_SHA"
        printf 'Failure bundle: %s\n' "$FAILURE_BUNDLE" >&2
        printf 'Failure SHA256: %s\n' "$FAILURE_BUNDLE_SHA" >&2
    else
        rm -f -- "$part"
    fi
}

on_error() {
    local rc="$1"
    local line="$2"
    local command_text="$3"
    trap - ERR
    set +e
    printf 'ERROR: Stage 15A SSOT update failed at line %s (exit %s): %s\n' "$line" "$rc" "$command_text" >&2
    if [[ "$MUTATION_STARTED" == "true" ]]; then
        restore_ssot
    fi
    rm -f -- "$OUTPUT_BUNDLE.part.$$" "$OUTPUT_BUNDLE_SHA.part.$$" 2>/dev/null || true
    create_failure_bundle "$rc" "$line" "$command_text"
    exit "$rc"
}
trap 'on_error "$?" "$LINENO" "$BASH_COMMAND"' ERR

[[ "$PROJECT_ROOT" == "/mnt/intelssd/rnatr_project" ]] || die "unexpected project root"
