    "$SSOT_CLI" "$SSOT_DB" "$REFERENCE_QC" "$REFERENCE_TIMING" \
    "$PACKAGE_MANIFEST" "$RUNNER" "$TSV_VALIDATOR" "$PACKAGE_VALIDATOR"
