printf '%s' '' | base64 -d > "$WORK_ROOT/RNA_TR_Scout_Stage15A_reference_SSOT_registration_v0.1.0.md"

BASELINE_CLI_SHA="$(sha256_file "$SSOT_CLI")"
BASELINE_DB_SHA="$(sha256_file "$SSOT_DB")"
SOURCE_ALREADY_PATCHED=false
