def sha256(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def read_metric_tsv(path: Path) -> dict[str, str]:
    with path.open("r", encoding="utf-8", newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        if reader.fieldnames != ["metric", "value"]:
            raise SystemExit(f"invalid metric TSV header: {path}: {reader.fieldnames}")
        rows = list(reader)
    keys = [row["metric"] for row in rows]
    if len(keys) != len(set(keys)):
        raise SystemExit(f"duplicate metric keys: {path}")
    return {row["metric"]: row["value"] for row in rows}


def data_rows(path: Path) -> int:
    opener = gzip.open if path.name.endswith(".gz") else open
    count = 0
    with opener(path, "rb") as handle:
        for _ in handle:
            count += 1
    if count == 0:
        raise SystemExit(f"empty table artifact: {path}")
    return count - 1


def snapshot_pipeline(conn: sqlite3.Connection, path: Path) -> list[sqlite3.Row]:
    cursor = conn.execute("SELECT * FROM current_pipeline ORDER BY stage_order,stage_key")
    fields = [item[0] for item in cursor.description or []]
    rows = cursor.fetchall()
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.writer(handle, delimiter="\t", lineterminator="\n")
        writer.writerow(fields)
        for row in rows:
            writer.writerow(["." if value is None else value for value in row])
    return rows


for path, expected in EXPECTED_HASHES.items():
    if not path.is_file():
        raise SystemExit(f"missing frozen file: {path}")
    observed = sha256(path)
    if observed != expected:
        raise SystemExit(f"frozen SHA mismatch: {path}: {observed} != {expected}")

qc = read_metric_tsv(QC)
for key, expected in EXPECTED_QC.items():
    if qc.get(key) != expected:
        raise SystemExit(f"Stage15A QC mismatch: {key}: {qc.get(key)!r} != {expected!r}")

