with TIMING.open("r", encoding="utf-8", newline="") as handle:
    reader = csv.DictReader(handle, delimiter="\t")
    required = {"stage", "execution_mode", "elapsed_seconds", "production_component"}
    if reader.fieldnames is None or not required.issubset(reader.fieldnames):
        raise SystemExit("Stage15A timing header mismatch")
    for row in reader:
        if row["stage"] in timing_rows:
            raise SystemExit(f"duplicate timing stage: {row['stage']}")
        timing_rows[row["stage"]] = row
if set(timing_rows) != set(EXPECTED_TIMING):
    raise SystemExit(f"timing stage set mismatch: {sorted(timing_rows)}")
