    row = timing_rows[stage]
    observed = (row["execution_mode"], row["elapsed_seconds"], row["production_component"])
    if observed != expected:
        raise SystemExit(f"timing mismatch for {stage}: {observed} != {expected}")

with MANIFEST.open("r", encoding="utf-8", newline="") as handle:
