    required = ["artifact", "table", "rows", "bytes", "sha256", "path"]
    if reader.fieldnames != required:
        raise SystemExit(f"package manifest header mismatch: {reader.fieldnames}")
    manifest_rows = list(reader)
if len(manifest_rows) != 10:
    raise SystemExit(f"package manifest row count mismatch: {len(manifest_rows)}")
if {row["artifact"] for row in manifest_rows} != set(EXPECTED_ARTIFACTS):
    raise SystemExit("package artifact set mismatch")

verified_artifacts = 0
for row in manifest_rows:
    artifact = row["artifact"]
    expected_table, expected_rows, expected_bytes, expected_sha = EXPECTED_ARTIFACTS[artifact]
    expected_path = PACKAGE_ROOT / artifact
    path = Path(row["path"])
    if path != expected_path:
        raise SystemExit(f"package path mismatch for {artifact}: {path} != {expected_path}")
    if path.is_symlink():
        raise SystemExit(f"package artifact must not be a symlink: {path}")
    if not path.is_file():
        raise SystemExit(f"package artifact missing: {path}")
    resolved = path.resolve()
    try:
        resolved.relative_to(PACKAGE_ROOT)
    except ValueError as exc:
        raise SystemExit(f"package artifact escapes package root: {path}") from exc
    if row["table"] != expected_table:
        raise SystemExit(f"package table mismatch for {artifact}")
    if int(row["rows"]) != expected_rows:
        raise SystemExit(f"manifest row count mismatch for {artifact}")
    if int(row["bytes"]) != expected_bytes or path.stat().st_size != expected_bytes:
        raise SystemExit(f"byte-size mismatch for {artifact}")
    if row["sha256"] != expected_sha or sha256(path) != expected_sha:
        raise SystemExit(f"SHA mismatch for {artifact}")
