insertion = Path(sys.argv[2]).read_text(encoding="utf-8")
expected_baseline_sha = sys.argv[3]
qc_path = Path(sys.argv[4])
marker = "# Stage 15A reference SSOT registration v0.1.0"
anchor = "    current_metrics = [\n"


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()

text = cli.read_text(encoding="utf-8")
before_sha = sha256(cli)
status = "ALREADY_PRESENT"

if insertion in text:
    if text.count(marker) != 1:
        raise SystemExit(f"Stage15A source marker count mismatch: {text.count(marker)}")
else:
    if marker in text:
        raise SystemExit("Stage15A marker exists but the frozen insertion block is not byte-identical")
    if before_sha != expected_baseline_sha:
        raise SystemExit(f"unexpected unpatched SSOT source SHA: {before_sha}")
    required = [
        "def add_decision(",
        "def add_interpretation(",
        "def source_document(",
        "def sha256_file(",
        "CREATE TABLE failures",
        "CREATE TABLE metrics",
        "CREATE TABLE open_questions",
        "CREATE TABLE limitations",
    ]
    missing = [token for token in required if token not in text]
    if missing:
        raise SystemExit("SSOT structural preflight failed: " + ", ".join(missing))
    if text.count(anchor) != 1:
        raise SystemExit(f"SSOT current_metrics anchor count={text.count(anchor)}")
    text = text.replace(anchor, insertion + "\n" + anchor, 1)
    if text.count(marker) != 1 or insertion not in text:
        raise SystemExit("Stage15A insertion verification failed")
    temp = cli.with_name(f".{cli.name}.stage15a_reference_v010.part")
    temp.write_text(text, encoding="utf-8")
    py_compile.compile(str(temp), doraise=True)
    temp.replace(cli)
    cli.chmod(0o755)
    status = "APPLIED"

