        ("source_patch_status", status),
        ("ssot_cli_sha256_before", before_sha),
        ("ssot_cli_sha256_after", after_sha),
        ("stage15a_marker_count", "1"),
        ("frozen_insertion_byte_exact", "true"),
        ("python_compile", "PASS"),
    ])
