PUBLISHED_DESIGN=true
cp -a "$WORK_ROOT/preflight.qc.tsv" "$WORK_ROOT/source_patch.qc.tsv" \
    "$WORK_ROOT/postcheck.qc.tsv" "$WORK_ROOT/update_contract.tsv" \
    "$WORK_ROOT/current_pipeline.before.tsv" "$WORK_ROOT/current_pipeline.after.tsv" \
    "$META_INSTALL/"
cp -a "$LOG_ROOT" "$META_INSTALL/logs"
PUBLISHED_META=true
cp -a "$WORK_ROOT/stage15a_ssot_update.qc.tsv" "$UPDATE_QC_INSTALL/stage15a_ssot_update.qc.tsv"
PUBLISHED_QC=true

OUTPUT_PART="$OUTPUT_BUNDLE.part.$$"
OUTPUT_SHA_PART="$OUTPUT_BUNDLE_SHA.part.$$"
rm -f -- "$OUTPUT_PART" "$OUTPUT_SHA_PART"
tar -C "$WORK_ROOT" -czf "$OUTPUT_PART" "$(basename "$BUNDLE_ROOT")"
printf '%s  %s\n' "$(sha256_file "$OUTPUT_PART")" "$(basename "$OUTPUT_BUNDLE")" > "$OUTPUT_SHA_PART"
mv -f "$OUTPUT_PART" "$OUTPUT_BUNDLE"
mv -f "$OUTPUT_SHA_PART" "$OUTPUT_BUNDLE_SHA"

SUCCESS=true
MUTATION_STARTED=false
trap - ERR

say
say "===== STAGE 15A REFERENCE SSOT UPDATE COMPLETE ====="
column -ts $'\t' "$WORK_ROOT/stage15a_ssot_update.qc.tsv" 2>/dev/null || cat "$WORK_ROOT/stage15a_ssot_update.qc.tsv"
say
say "Installed script:  $SCRIPT_INSTALL"
say "Design record:     $DESIGN_INSTALL"
say "SSOT update QC:    $UPDATE_QC_INSTALL/stage15a_ssot_update.qc.tsv"
say "Output bundle:     $OUTPUT_BUNDLE"
say "Bundle SHA256:     $OUTPUT_BUNDLE_SHA"
say "Next gate:         BUILD_AND_RUN_STAGE15A_PERFORMANCE_CANDIDATE"
say "STAGE15A_REFERENCE_SSOT_UPDATE_PASS"
